function CashFlows()
local RES= teamyar.query(context,[[{"query":"with recursive CTE_Account AS (SELECT ID as SourceAccount,ID as AccountID, CODE AS AccountCode, PARENT , ORG_ID AS ORG_ID FROM pa_account WHERE ORG_ID = 2 UNION SELECT  CTE_Account.SourceAccount as SourceAccount,pa.ID as AccountID, pa.CODE AS AccountCode, pa.PARENT , pa.ORG_ID AS ORG_ID FROM CTE_Account INNER JOIN pa_account as pa ON CTE_Account.AccountID = pa.PARENT and CTE_Account.ORG_ID = pa.ORG_ID), CTE_DateRangePerYear as (select min(JNDATE) as MinJndate,max(JNDATE) as MaxJndate,min(DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) as sdate,  max(DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) edate, JYEAR FROM REPORT_DIMDATE where (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) >= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) <= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 133553537990000000)) group by JYEAR), CTE_VoucherRecords as  (select cte_DateRangePerYear.MaxJndate as Jndate,cte_DateRangePerYear.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,SUM(COALESCE(pvr.CRD, 0) - COALESCE(pvr.DEB, 0)) as remain,TAG_ID from cte_DateRangePerYear inner join pa_voucher as pv on pv.RUN_DATE >= sdate and pv.RUN_DATE <= edate inner join pa_voucher_record as pvr on pv.ID = pvr.VOUCHER_ID and pv.ORG_ID = pvr.ORG_ID INNER JOIN PA_VOUCHER_RECORD_TAG vrt ON vrt.VOUCHER_RECORD_ID = pvr.ID and vrt.ORG_ID = pvr.ORG_ID  where pv.ORG_ID = 2 and (pv.RUN_DATE >=132922818000000000 and pv.RUN_DATE <= 133552800000000000) /* and pv.type in (1,4,5) and pv.status in(2,4,5,6)*/ and pv.deleted = 0 and pvr.deleted = 0 group by MaxJndate,JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,vrt.TAG_ID) , CTE_MinDateRange AS (SELECT min(MinJndate) as MinJndate,min(JYEAR) JYEAR,min(sdate) sdate ,min(edate) edate FROM cte_DateRangePerYear),CTE_AccountsVouchers AS (select CTE_Account.SourceAccount,CTE_Account.ORG_ID,sum(CTE_VoucherRecords.remain) as remain,CTE_VoucherRecords.Jndate,CTE_VoucherRecords.JYEAR,TAG_ID from CTE_Account INNER JOIN CTE_VoucherRecords on CTE_Account.AccountID=CTE_VoucherRecords.ACCOUNT_ID and CTE_Account.ORG_ID=CTE_VoucherRecords.ORG_ID group by CTE_Account.SourceAccount,CTE_Account.ORG_ID,CTE_VoucherRecords.Jndate,CTE_VoucherRecords.JYEAR,TAG_ID), CTE_RemainAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain,Jndate, JYEAR, 1 as type,TAG_ID from CTE_AccountsVouchers where TAG_ID>=0 group by ORG_ID,Jndate,JYEAR,TAG_ID), cte_DecimalCount as (select ps.ORG_ID,ps.ID,ps.name,ps.DECIMAL_COUNT,ps.FEE_DECIMAL from PA_ORGANIZATIONS as po inner join PA_SYMBOLS as ps on po.BASE_CURRENCY = ps.id and po.ORG_ID = ps.ORG_ID), Cte_RemainAccountsBaseDecimalCount as (select uor.ORG_ID,oi.NAME as OrgName,  COALESCE(uor.remain, 0)/POWER(10, COALESCE(cdc.DECIMAL_COUNT, 0)) as remain , uor.JYEAR,uor.JNDATE, uor.type,uor.TAG_ID  from CTE_RemainAccounts uor left join cte_DecimalCount cdc on uor.ORG_ID = cdc.ORG_ID left join org_info oi on uor.ORG_ID = oi.ID) SELECT JSON_ARRAYAGG(JSON_OBJECT( 'ORG_ID',RA.ORG_ID, 'OrgName',RA.OrgName,'type',RA.type,'JYEAR',RA.JYEAR,'JNDATE',RA.JNDATE,'TAG_ID',RA.TAG_ID,'remain',RA.remain, 'title',PVT.NAME)) as result from Cte_RemainAccountsBaseDecimalCount RA LEFT JOIN pa_voucher_tag PVT ON  RA.ORG_ID = PVT.ORG_ID AND RA.TAG_ID = PVT.ID where RA.JYEAR>=0 order by RA.JYEAR ASC,RA.type;","params":[]}]]);
teamyar.write_result(context,RES)
end

CashFlows()